 raw=pickle.loads(source.read_bytes());truth={tuple(x) for x in raw['simulation']['truth']['truth_supports']};internal={s for s in truth if 1<len(s)<15};labels=f['terminal_labels'];cal=f['calibrations']['raw'];cs=f['selection_candidates'];best=min(c['validation_mae'] for c in cs)
